style.css:
@-moz-document domain("bbc.com"), url-prefix("https://www.bbc.co.uk/news"), url-prefix("https://www.bbc.co.uk/sport"), url-prefix("https://bbc.co.uk/news"), url-prefix("https://bbc.co.uk/sport"), url-prefix("http://www.bbc.co.uk/news"), url-prefix("http://www.bbc.co.uk/sport") {
/* ============================================================
     BBC ships NO CSS custom-property theme system — colours are
     hardcoded per component across two frontends:
       • "Dotcom" React (home / News front / articles): stable
         data-testid + data-component hooks, styled-components whose
         hashed suffix changes but whose readable prefix is stable
         (e.g. Header-styles__HeaderStyled-sc-… → match on the FULL
         "Header-styles__HeaderStyled", never the bare "HeaderStyled",
         which also hits SocialFollowUs-styles__SocialFollowUsHeaderStyled).
       • Legacy Simorgh "ssrcss" (Sport): Emotion classes
         ssrcss-<hash>-<ComponentName>; the <ComponentName> suffix is
         stable  →  [class*="GlobalNavigation"], [class*="StyledParticipant"].
     We retheme by targeting those stable hooks, never the hashes.
     Every [class*=…] token must be the longest distinguishing string:
     a bare [class*="Win"] once matched Windsor-styles__* and painted a
     promo's copy green.
     Palette: official Catppuccin Mocha, inlined (self-contained).
     ============================================================ */

  :root {
    color-scheme: dark !important;
    /* Catppuccin Mocha */
    --ctp-base:     #1e1e2e;
    --ctp-mantle:   #181825;
    --ctp-crust:    #11111b;
    --ctp-surface0: #313244;
    --ctp-surface1: #45475a;
    --ctp-overlay1: #7f849c;
    --ctp-overlay2: #9399b2;
    --ctp-subtext0: #a6adc8;
    --ctp-subtext1: #bac2de;
    --ctp-text:     #cdd6f4;
    --ctp-blue:     #89b4fa;
    --ctp-sky:      #89dceb;
    --ctp-mauve:    #cba6f7;
    --ctp-red:      #f38ba8;
    --ctp-yellow:   #f9e2af;
    --ctp-green:    #a6e3a1;
    --ctp-teal:     #94e2d5;
  }

  /* ---- Base surfaces ---- */
  html, body {
    background-color: var(--ctp-base) !important;
    color: var(--ctp-text) !important;
  }

  /* Soften every default light border to a subtle Mocha surface line.
     Semantic / coloured borders are restored further down. */
  * { border-color: var(--ctp-surface0) !important; }

  /* Links default to light text (BBC headlines/nav ARE links and read as
     plain text, not blue). Specific accent links (article body, footer,
     nav-hover) override below. This also rescues the volatile pure-hash
     Sport global-nav anchors that carry no stable hook. */
  a { color: var(--ctp-text) !important; }
  nav a, header a, [role="navigation"] a { color: var(--ctp-text) !important; }
  nav a:hover, header a:hover { color: var(--ctp-sky) !important; }

  /* Accessibility skip-link (black on white, shown on focus) */
  [class*="SkipLink"], [class*="SkipLink"] a {
    background-color: var(--ctp-mantle) !important;
    color: var(--ctp-text) !important;
  }

  /* ============================================================
     DOTCOM REACT FRONTEND  (home / News front / articles)
     ============================================================ */

  /* ---- Masthead / global header ----
     Anchor on the FULL component name: a bare [class*="HeaderStyled"] also
     matches SocialFollowUs-styles__SocialFollowUsHeaderStyled and painted a
     mantle rectangle behind the footer's "Follow BBC on:" label. */
  header,
  [class*="Header-styles__HeaderStyled"],
  [data-testid="level1-navigation-container"],
  [class*="GlobalNavigationBar"] {
    background-color: var(--ctp-mantle) !important;
    color: var(--ctp-text) !important;
    border-color: var(--ctp-surface0) !important;
  }
  /* The BBC blocks logo and nav glyphs paint via fill:currentColor —
     inheriting the light header colour keeps the brand shape, just
     visible. Do NOT recolour them to an accent. */
  header svg { color: var(--ctp-text) !important; }

  /* Combined menu/search toggle (top-left) ships a solid white box in
     both closed (hamburger+search glyphs) and open (X) states — a glaring
     white square with a near-invisible light icon. Darken to a surface
     tile so the icon reads. (36px wide → below the audit big() threshold.) */
  [class*="HeaderMenuButtonStyled"] {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
    border-color: var(--ctp-surface1) !important;
  }
  [class*="HeaderMenuButtonStyled"] svg { color: var(--ctp-text) !important; }

  /* The red "BBC NEWS" section wordmark (NestedNavigation NewsLogoContainer) is a
     brand #b80000 <svg> filled via currentColor; our generic h1/header colour rule
     flattened it to plain light text, dropping the News identity the theme keeps
     everywhere else (LIVE badge, breaking flag, 404 kicker all use the Mocha red).
     This is the News wordmark only — the top BBC-blocks logo is a separate
     container and stays light. Restore the readable brand red. */
  [class*="NewsLogoContainer"] svg,
  [class*="NewsLogoContainer"] svg path {
    color: var(--ctp-red) !important;
    fill: var(--ctp-red) !important;
  }

  /* ---- Top navigation links / items ---- */
  [data-testid^="navigationPanel-navItem"],
  [data-testid^="level0NavButton"],
  [data-testid="search-input-wrapper"],
  [class*="SearchInputBoxedStyled"],
  [data-testid="drawer-background"],
  [class*="NavigationPanel"],
  [class*="MenuColumns"],
  [class*="DropdownStyled"],
  [class*="LanguageDropdown"] {
    background-color: var(--ctp-mantle) !important;
    color: var(--ctp-text) !important;
  }
  [data-testid="mainNavigationLink"],
  [data-testid="subNavigationLink"],
  [data-testid^="navigationPanel-navItem"] a,
  [class*="mainNavigationLink"],
  [class*="NavLink"] {
    color: var(--ctp-text) !important;
  }
  [data-testid="mainNavigationLink"]:hover,
  [data-testid="subNavigationLink"]:hover,
  [class*="NavLink"]:hover { color: var(--ctp-sky) !important; }

  /* Active top-nav item is marked ONLY by a 4px li::after bar. Every section
     but News paints it pure black (News uses the brand #b80000), so on the
     dark masthead the "you are here" cue disappears on Home / Business /
     Culture / Travel and the mobile nav panel. `*` never matches a pseudo,
     so no other rule reaches it. Repaint with the readable Mocha red — the
     BBC brand accent this indicator already carries on News. The bar only
     renders on the current item (content:none elsewhere). */
  li[class*="MainNavigationItemStyled"]::after {
    background-color: var(--ctp-red) !important;
  }
  /* Same indicator in the slide-out nav panel (the only nav at 390px): an
     8x44 black ::before rail on the current item. Its siblings share the
     class and differ only by a bare `selected` attribute, so key off that —
     a blanket rule would draw a rail beside every item. */
  [class*="NavButtonStyled"][selected]::before {
    background-color: var(--ctp-red) !important;
  }

  /* ---- Page section wrappers (keep transparent over base) ---- */
  main,
  /* Sections use US-state codenames with an optional trailing index
     (e.g. georgia-section-outer-4) — a $="…-section-outer" suffix match
     misses the numbered variants and lets a special-report section
     (e.g. the "AMERICA 250" band) ship its white bg. Match on *= so every
     …-section-outer/-inner is caught regardless of the trailing number. */
  [data-testid*="-section-outer"],
  [data-testid*="-section-inner"],
  [data-testid^="ohio-section"],
  [data-testid^="nevada-section"],
  [data-testid^="illinois-section"],
  [data-testid="section-outer-wrapper"],
  [class*="GridContainer"],
  [class*="ContentWrapper"],
  [class*="PageWrapper"] {
    background-color: transparent !important;
  }

  /* ---- Story cards / promos ---- */
  [data-testid$="-card"],
  [data-testid$="-article"],
  [data-testid="card-image-wrapper"],
  [data-testid="card-media"],
  [data-testid="card-text-wrapper"],
  [class*="CardWrapper"],
  [class*="PromoWrapper"] {
    background-color: transparent !important;
  }
  /* Windsor = the big featured/lead promo (ships a solid white bg) */
  [class*="WindsorAnchor"],
  [class*="Windsor-styles"] {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
  }
  [data-testid="card-headline"],
  [class*="PromoHeadline"],
  [class*="Headline"] {
    color: var(--ctp-text) !important;
  }
  /* Card separators are <hr>s coloured by background-color, not border — the
     `*` border rule cannot reach them, and a 1px #e6e8ea rule is a glaring
     white hairline on the dark base. Only the stacked (mobile) card layouts
     render them, so a desktop-only pass never sees it. Covers every card
     family's SeparatorStyled, including the footer's. */
  hr[class*="SeparatorStyled"] {
    background-color: var(--ctp-surface0) !important;
  }
  [data-testid="card-description"],
  [class*="PromoBody"],
  [class*="Summary"],
  /* Search-results "Newport" card: its description area ships hardcoded
     near-black #202224 — dark-on-dark once the page is darkened (the headline
     + metadata already read via the Headline/Metadata rules, only the summary
     was missed). Its class is NewportDescriptionAreaStyled, caught by neither
     card-description nor PromoBody/Summary. */
  [class*="NewportDescription"] {
    color: var(--ctp-subtext1) !important;
  }
  /* Same Newport search card: the brand/strand kicker above the headline
     ("Thought for the Day", "Witness History", "Asia Specific") ships
     hardcoded #545658 (~2:1 on the base, a WCAG fail) — dark-on-dark once
     darkened. Its class is NewportBrandNameStyled, missed by every card /
     metadata rule. Lift to the readable muted Mocha metadata tone. */
  [class*="NewportBrandName"] {
    color: var(--ctp-subtext0) !important;
  }
  /* Search-results pagination: each page tile is a 44×44 anchor with a
     hardcoded #f6f6f6 fill (under the audit's 120×40 big() filter, so the
     lightSurfaces scan never flags it) — our light link colour on it left the
     page numbers white-on-white. Dark tile, light number.
     KNOWN GAP: BBC marks the CURRENT page by giving that one tile a black fill, and the
     only thing that distinguishes it from its neighbours is the styled-components hash
     (its href, title and data-testid are identical to every other page tile), so the
     "you are here" cue cannot be restored with a stable selector. The disabled
     prev/next arrows DO carry href="#", so those keep their dimmed state. */
  [class*="PaginationAnchorStyled"] {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
    border-color: var(--ctp-surface1) !important;
  }
  [class*="PaginationAnchorStyled"][href="#"] {
    color: var(--ctp-overlay1) !important;
    border-color: var(--ctp-surface0) !important;
  }
  [class*="PaginationAnchorStyled"]:hover {
    background-color: var(--ctp-surface1) !important;
    color: var(--ctp-text) !important;
  }
  /* Card media badge (the play/audio glyph chip pinned over the artwork).
     BBC ships it in two native flavours — white chip + black glyph (Ipswich,
     London, Dundee) and black chip + white glyph (Edinburgh, Windsor) — and
     our metadata rule greyed every glyph to overlay2. The old parent-scoped
     fix (ImageContainer / CardMedia) reached only two of the five card
     families: London kept its white chip under a ~2.5:1 washed-out triangle,
     and Edinburgh/Windsor lost their crisp white glyph. Target the chip
     component itself so all five match. The prefix is exact:
     IndexCardContentTypeLabel-styles__ContentTypeLabelStyled can never match
     the inline LIVE badge (IndexCardHeading-styles__ContentTypeLabel…), whose
     dot must stay brand red. */
  [class*="IndexCardContentTypeLabel-styles__ContentTypeLabelStyled"] {
    background-color: var(--ctp-crust) !important;
    color: var(--ctp-text) !important;
  }
  [class*="IndexCardContentTypeLabel-styles__ContentTypeLabelStyled"] svg,
  [class*="IndexCardContentTypeLabel-styles__ContentTypeLabelStyled"] svg path {
    color: var(--ctp-text) !important;
    fill: var(--ctp-text) !important;
  }
  /* The inline glyph beside a "Watch:"/"Listen:" card headline is a 16px SVG
     with a hardcoded #202224 fill → invisible on the dark base. Its wrapper
     class is identical to the LIVE pulse dot's, so key off the icon's own
     data-testid to leave the brand-red live dot alone. */
  svg[data-testid="inline-icon"] path {
    fill: var(--ctp-text) !important;
  }

  /* data-testid="content-type-label" is NOT metadata text — it is the media
     badge chip above, and listing it here is what dimmed its glyph. */
  [data-testid="card-metadata-lastupdated"],
  [data-testid="card-metadata-tag"],
  [data-testid="card-metadata-separator"],
  [class*="MetadataStripStyled"],
  [class*="Timestamp"],
  time {
    color: var(--ctp-overlay2) !important;
  }

  /* ---- Section titles ---- */
  [data-testid="section-title-wrapper"],
  [data-testid="section-title-wrapper"] *,
  [class*="SectionTitle"],
  [class*="StyledSectionLabel"] {
    color: var(--ctp-text) !important;
    background-color: transparent !important;
    border-color: var(--ctp-surface1) !important;
  }

  /* ============================================================
     ARTICLE READING VIEW  (bbc.com/news/articles/*)
     ============================================================ */
  article,
  [data-component="headline-block"],
  [data-component="byline-block"],
  [data-component="text-block"],
  [data-component="layout-block"],
  [data-component="image-block"],
  [data-component="tag-list-block"],
  [data-component="links-block"],
  [data-component="unordered-list-block"],
  [data-component="ordered-list-block"] {
    background-color: transparent !important;
  }
  article h1, [data-component="headline-block"] h1,
  article h2, article h3, article h4 {
    color: var(--ctp-text) !important;
  }
  [data-component="text-block"] p,
  [data-component="text-block"] li,
  article p, article li {
    color: var(--ctp-subtext1) !important;
  }
  /* Inline links inside article body get the accent. */
  [data-component="text-block"] a,
  [data-component="links-block"] a,
  article p a, article li a {
    color: var(--ctp-blue) !important;
  }
  [data-component="text-block"] a:hover,
  article p a:hover { color: var(--ctp-sky) !important; }
  /* Byline / contributor */
  [data-component="byline-block"],
  [data-component="byline-block"] *,
  [data-testid="byline-new"],
  [class*="Contributor"],
  /* live-post reporter name is a <strong> with its own hardcoded #181818 —
     the parent Contributor colour doesn't reach it */
  [class*="Contributor"] *,
  [class*="Byline"] {
    color: var(--ctp-subtext0) !important;
  }
  /* Image captions */
  figcaption,
  [data-component="image-block"] figcaption,
  [class*="Caption"] {
    color: var(--ctp-overlay2) !important;
  }
  /* Pull-quotes / blockquotes */
  blockquote,
  [data-component="quote-block"],
  [class*="PullQuote"],
  [class*="Blockquote"] {
    color: var(--ctp-text) !important;
    border-color: var(--ctp-mauve) !important;
    background-color: var(--ctp-mantle) !important;
  }
  [data-component="quote-block"] *,
  [class*="PullQuote"] * { color: var(--ctp-text) !important; }

  /* "More on this story" / "Related" rail title is a <span>, not a heading, and
     ships hardcoded #202224 → 1.2:1 on the base, effectively invisible. */
  [class*="LinksTitleStyled"] {
    color: var(--ctp-text) !important;
  }

  /* ---- Related-story rails / tag chips ---- */
  [data-testid="tag-list"] a,
  [data-component="tag-list-block"] a,
  [class*="TagListStyled"] a,
  [class*="TopicList"] a {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-subtext1) !important;
    border-color: var(--ctp-surface1) !important;
  }
  [data-testid="tag-list"] a:hover,
  [data-component="tag-list-block"] a:hover {
    background-color: var(--ctp-surface1) !important;
    color: var(--ctp-text) !important;
  }

  /* ============================================================
     SPORT  (legacy ssrcss frontend)
     ============================================================ */
  [class*="GlobalNavigation"],
  [class*="NavigationContainer"],
  [class*="StaticLinks"] {
    background-color: var(--ctp-mantle) !important;
    color: var(--ctp-text) !important;
    border-color: var(--ctp-surface0) !important;
  }
  [class*="NavigationLink"] { color: var(--ctp-text) !important; }
  [class*="NavigationLink"]:hover { color: var(--ctp-sky) !important; }
  /* The account / "For You" avatar disc in the global nav is BBC blue #0071f1
     (the one chromatic glyph in an otherwise monochrome bar — it is what marks
     the sign-in affordance). Our `header svg` rule flattened it to plain light,
     so it read as just another nav icon. Restore the Mocha blue. */
  [class*="ForYouIconWrapper"] svg,
  [class*="ForYouIconWrapper"] svg path {
    color: var(--ctp-blue) !important;
    fill: var(--ctp-blue) !important;
  }
  [class*="SearchLink"], [class*="NavigationLink-Search"] {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
  }

  /* Match / fixture / score strips (HeadToHead carousel, SPC).
     Scoped descendant text → light; live/score accents restored below. */
  [class*="StyledStrip"], [class*="HeadToHead"],
  [class*="StyledStrip"] *, [class*="HeadToHead"] *,
  [class*="Competition"], [class*="LeftSection"], [class*="RightSection"],
  [class*="StyledTime"], [class*="StyledDate"], [class*="OnwardJourney"],
  [class*="CarouselItem"], [class*="FixtureWrapper"], [class*="MatchStatus"] {
    color: var(--ctp-text) !important;
  }
  [class*="HeadToHeadContai"], [class*="StyledStrip"],
  [class*="MatchPromo"], [class*="StyledFixture"] {
    background-color: var(--ctp-surface0) !important;
    border-color: var(--ctp-surface1) !important;
  }
  /* The kick-off time block inside a head-to-head fixture card is a <time>
     with a hardcoded #f8f8f8 fill (44px tall → under the audit's big()
     threshold). The HeadToHead descendant rule above had already lightened
     its text, so "FRI 20:00 10 JUL" rendered ~1.6:1 light-on-white. */
  [class*="HeadToHeadContainer"] time {
    background-color: var(--ctp-surface0) !important;
  }
  /* Each fixture card in the head-to-head carousel carries a 4px left rail that
     encodes its state: BBC-Sport yellow #ffd230 on a card that has a result to
     read (it is the only one wrapped in an OnwardJourneyLink anchor), near-black
     #181818 on the not-yet-played ones. Our blanket `* { border-color }` painted
     ALL of them the same surface line — erasing the "there is a result here" cue
     and drawing a phantom grey rail beside every upcoming fixture. Clear the rail
     by default (the native black one is invisible on dark anyway) and restore the
     brand yellow on the linked card. */
  [class*="ParticipantsWrapper"] {
    border-left-color: transparent !important;
  }
  a[class*="OnwardJourneyLink"] [class*="ParticipantsWrapper"] {
    border-left-color: var(--ctp-yellow) !important;
  }

  /* ---- Scores & Fixtures page (ssrcss) ----
     A redesigned match-list view our older Sport rules didn't cover: the
     whole content area ships #f8f8f8/#fff surfaces (page background, the
     team-search combobox, the competition header band, and every fixture
     row) — light-on-light, unreadable. Map them onto the Mocha surfaces.
     The combobox/header use generic component suffixes, so scope them to
     their stable parent wrapper. */
  [class*="BackgroundWrapper"],
  [class*="HeaderWrapper"], [class*="HeaderWrapper"] div,
  /* The Scores & Fixtures WIDGET embedded on a live-match / index page (section#Scores)
     wraps its dark fixture rows in a solid-#fff FixturesWrapper — a glaring white panel
     that leaves the "Monday 20th…" date heading and "View all fixtures" link light-on-
     white. The full-page fixtures view hides it under BackgroundWrapper, so a page-level
     pass never saw it. Drop it onto the base like the other fixture wrappers. */
  [class*="FixturesWrapper"] {
    background-color: transparent !important;
  }
  /* The fixtures reset above matches PersistentHeaderWrapper too (substring
     over-match): the position:fixed z-1004 live sticky header (LIVE dot,
     "Watch as…" strip, Listen-live) is natively opaque rgb(24,24,24) but got
     flattened to transparent, so the left-rail "Key moments" list bled through
     and overlapped its text. BBC now nests this fixed header INSIDE a HeaderWrapper
     ancestor, so the reset's `[class*="HeaderWrapper"] div` branch (0,1,1) out-specifies
     a bare `[class*="PersistentHeaderWrapper"]` (0,1,0) and re-flattened it to
     transparent (bleed-through returned). Match the div itself (0,1,1) and the nested
     form (0,2,1) so we out-specify the reset in both DOM shapes. */
  div[class*="PersistentHeaderWrapper"],
  [class*="HeaderWrapper"] div[class*="PersistentHeaderWrapper"] {
    background-color: var(--ctp-mantle) !important;
  }
  [class*="HeadToHeadWrapper"],
  [class*="StyledHeadToHead"] {
    background-color: var(--ctp-surface0) !important;
    border-color: var(--ctp-surface1) !important;
  }
  /* Each Scores & Fixtures row carries a 4px left rail: BBC-Sport yellow #ffd230 on
     a finished match (FT), near-black #181818 (invisible) on the not-yet-played and
     cancelled ones. The StyledHeadToHead border rule above painted EVERY rail surface1
     grey — a phantom rail beside upcoming/cancelled rows and a wrong-colour one on the
     finished ones. The finished-vs-other state is carried only by the row's status text
     and a volatile Emotion hash — no stable, sanitisation-surviving selector can single
     out the yellow rows — so clear the rail on all of them (FT is already conveyed by
     the "FT" label + score). The later longhand out-orders the shorthand above. */
  [class*="StyledHeadToHeadWrapper"] {
    border-left-color: transparent !important;
  }
  [class*="ComboboxWrapper"], [class*="ComboboxWrapper"] div,
  /* Team/competition search autocomplete: the open suggestion list ships a
     solid-white <ul>/<li> (StyledUl/StyledLi) that only appears once you type,
     so the closed-state audit misses it — it peeks out as a white strip beside
     the dark menu panel. The div-only rule above skipped the list elements. */
  [class*="ComboboxWrapper"] ul, [class*="ComboboxWrapper"] li {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
  }
  /* The date carousel's scroll-fade overlays paint a light #f8f8f8
     gradient (100px wide → under the audit big() width filter, so the
     lightBgImages scan misses them). Drop the gradient. */
  [class*="Datepicker"] [class*="Fade"],
  [class*="DatePicker"] [class*="Fade"] {
    background-image: none !important;
  }
  /* The date carousel marks the SELECTED day with a 3px green (#387b12) bottom
     border; every other day is transparent. Our blanket `* { border-color }`
     painted ALL of them surface0 — erasing the selected-day cue and drawing a
     phantom underline under every date. Reset the row to transparent and restore
     the selected day's indicator with the readable Mocha green (the attribute
     selector out-specifies the reset). The selected day is the only DateLink
     whose aria-label ends in "selected", stable across date navigation. */
  a[class*="EnabledDateLink"] {
    border-bottom-color: transparent !important;
  }
  a[class*="EnabledDateLink"][aria-label*="selected"] {
    border-bottom-color: var(--ctp-green) !important;
  }
  /* Promo/Shorts carousel edge overlays ship a solid rgba(248,248,248,.75)
     scroll-fade that washes the outermost card to light grey (bg-COLOR, not
     a gradient → the lightBgImages scan misses it; it slips the lightSurfaces
     size filter as a narrow strip). Re-tint to a translucent base so the
     fade cue survives but reads dark. */
  [class*="CarouselLeftOverlay"],
  [class*="CarouselRightOverlay"] {
    background-color: rgba(30, 30, 46, 0.75) !important;
    background-image: none !important;
  }
  /* "All times are UK…" disclaimer ships hardcoded near-black text — fine
     on the old light bg, dark-on-dark once we darken the page. */
  [class*="DisclaimerText"] {
    color: var(--ctp-subtext0) !important;
  }
  /* Scores & Fixtures ships a SEPARATE full-width disclaimer band ("Please note:
     All times are UK…") whose WRAPPER is a hardcoded #f8f8f8 box (SportDisclaimerWrapper,
     not the DisclaimerText above) → a glaring white strip above the footer. Its native
     text is near-black; darken the box and lift the text + the "Please note:" <strong>. */
  [class*="SportDisclaimerWrapper"] {
    background-color: var(--ctp-mantle) !important;
    color: var(--ctp-subtext0) !important;
    border-color: var(--ctp-surface0) !important;
  }
  [class*="SportDisclaimerWrapper"] strong {
    color: var(--ctp-subtext1) !important;
  }

  /* Image placeholders / loading tiles (light grey) */
  [class*="Placeholder"] {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-subtext0) !important;
  }
  /* Containers, fixtures, participants, coloured strips */
  [class*="-Container"],
  [data-testid="spc-container"],
  [class*="FixturesBanner"],
  [class*="ExtraContentWrapper"],
  [class*="StyledParticipant"] {
    background-color: transparent !important;
    color: var(--ctp-text) !important;
  }
  [class*="ColouredContainer"] {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
  }
  /* Newsletter / promo band CTA. BBC ships this button in two fills (solid
     white "Sign up", solid black "Discover more") and our light link colour
     left the white one at ~1.5:1. 88x44 → under the audit's big() floor.
     Give both the same readable dark pill. */
  [class*="ColouredContainer"] [class*="CallToActionLink"] {
    background-color: var(--ctp-surface1) !important;
    color: var(--ctp-text) !important;
    border-color: var(--ctp-overlay1) !important;
  }
  /* The "My Sport" band's artwork (the scattered Football/Cricket/Formula 1 tiles) is a
     background-IMAGE of black outlines on transparent — crisp on BBC's native #f0f0f0
     band, all but invisible once the band is a dark surface. No colour rule can reach a
     raster, so invert the artwork; the element is decorative and carries no text of its
     own, and the band's "Discover more" link is a sibling, so no click target is covered. */
  [class*="ColouredContainer"] [class*="StyledImage"] {
    filter: invert(1) !important;
  }
  [class*="StyledParticipant"],
  [class*="PromoHeadline"],
  [class*="PromoBody"],
  [class*="Headline"] a,
  [class*="StyledLink"] {
    color: var(--ctp-text) !important;
  }
  [class*="MetaData"],
  [class*="Timestamp"],
  [class*="StyledTimestamp"],
  [class*="LiveLabel"] ~ * {
    color: var(--ctp-overlay2) !important;
  }

  /* ---- Sport STORY frontend (ssrcss article + its rails) ----
     The related-story promo cards ("More on this story", the right-hand
     promo rail) ship a solid-white Promo card + white MediaContainer, and
     the "Related topics" pills are white LinkItem/StyledLink chips. Our
     Sport rules coloured the headline text light but never darkened these
     surfaces → light-on-white, unreadable. `[class*="-Promo"]` targets the
     exact Emotion component "Promo" (leading hyphen) without touching
     "MatchPromo". Cards sit transparent on the base; chips become dark pills. */
  [class*="-Promo"],
  [class*="IndexPromo"],
  [class*="MediaContainer"],
  [class*="PromoContentWrapper"] {
    background-color: transparent !important;
  }
  /* Sport-story byline "BBC Sport journalist at …" ships hardcoded #606060,
     readable on the old white bg but dark-on-dark once darkened. */
  [class*="ContributorDetails"],
  [class*="ContributorDetails"] * {
    color: var(--ctp-subtext0) !important;
  }
  /* Live "…viewing" count is hardcoded BBC-Sport teal #006666 (~1.6:1 on the
     Mocha base, invisible). All other MetadataText already reads as subtext1,
     so pin the whole class to the readable subtext for a consistent metadata. */
  [class*="MetadataText"] { color: var(--ctp-subtext1) !important; }
  [class*="LinkItem"] { background-color: transparent !important; }
  [class*="LinkItem"] [class*="StyledLink"],
  [class*="TagList"] [class*="StyledLink"],
  [class*="Cluster"] [class*="StyledLink"] {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-subtext1) !important;
    border-color: var(--ctp-surface1) !important;
  }
  [class*="PageTypeIndicator"] {
    background-color: var(--ctp-mantle) !important;
    color: var(--ctp-text) !important;
  }
  /* Share flyout (the panel behind every live-post / story "Share" button, and the
     same information-panel component elsewhere in ssrcss). It is rendered only once
     you CLICK, so no load-time scan ever sees it: a solid #fff panel carrying a
     brand-yellow "Copy link" and close button whose labels BBC paints black. Our
     page rules landed light text on both surfaces — "About sharing" at ~1.4:1 on the
     white panel, "Copy link" at ~1.7:1 on the yellow pill. Darken the panel, lift its
     links, and put the dark label back on the yellow buttons. The caret that points at
     the Share button is the panel's own ::before/::after (a light-grey rotated square,
     not a child element), so `*` never reaches it and it stayed a white notch on the
     darkened panel. */
  [class*="StyledPanelContent"] {
    background-color: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
  }
  [class*="StyledPanelContent"] [class*="StyledTitleArea"] {
    color: var(--ctp-text) !important;
  }
  [class*="StyledPanelContent"] a {
    color: var(--ctp-blue) !important;
  }
  [class*="StyledPanelContent"] button,
  [class*="StyledPanelContent"] button span {
    color: var(--ctp-crust) !important;
  }
  [class*="StyledPanelContent"] button svg,
  [class*="StyledPanelContent"] button svg path {
    color: var(--ctp-crust) !important;
    fill: var(--ctp-crust) !important;
  }
  [class*="StyledPanelContent"]::before,
  [class*="StyledPanelContent"]::after {
    background-color: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface0) !important;
  }
  /* Match-coverage promo card embedded in a Sport story ("Mexico v England /
     Watch on iPlayer / Listen: …") ships a solid-white EventInformationContainer.
     Our generic p/li + heading rules had already lightened its text, so the card
     rendered light-on-WHITE — unreadable. It carries no -Promo/-Card hook (its
     class is EventInformationContainer), so the Sport-story surface rules missed
     it. Darken the card and lift its hardcoded #606060 detail/coverage/links text
     (dark-on-dark once the card is dark) to a readable muted Mocha. */
  [class*="EventInformationContainer"] {
    background-color: var(--ctp-surface0) !important;
    border-color: var(--ctp-surface1) !important;
  }
  [class*="EventDetailsContainer"],
  [class*="CoverageTextContainer"],
  [class*="CallToActionContainer"],
  [class*="AdditionalLinksContainer"] {
    color: var(--ctp-subtext0) !important;
  }
  /* "Get in touch" contribution banner (ssrcss, end of many Sport/News stories):
     a solid-white Content box ("Get in touch / Send us your feedback / Contact
     form") our text rules had already lightened → light-on-white, and its native
     brand-yellow #ffd230 "Contact form" CallToActionLink label/icon read light-on-
     yellow. [class*="-Content "] (note the trailing space) matches ONLY the Emotion
     component whose label is exactly "Content" — this banner — never ContentWrapper /
     PromoContent / MetadataContent / CarouselContent (no "-Content " substring in
     those). Darken the box; put the dark label back on the yellow CTA. */
  [class*="-Content "] {
    background-color: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface0) !important;
  }
  /* The visible "Contact form" CTA is a JS-rendered ssrcss `Button` (eoocusk1),
     NOT the no-JS `CallToActionLink` fallback beside it — our generic `button`
     rule lightened its label/icon → light-on-yellow. Scoped to this banner (its
     only button is the yellow CTA), so the 43 transparent ghost `eoocusk1`
     buttons elsewhere keep their light text. */
  [class*="-Content "] button,
  [class*="-Content "] button span,
  [class*="-Content "] [class*="CallToActionLink"],
  [class*="-Content "] [class*="CallToActionLink"] span {
    color: var(--ctp-crust) !important;
  }
  [class*="-Content "] button svg,
  [class*="-Content "] button svg path,
  [class*="-Content "] [class*="CallToActionLink"] svg,
  [class*="-Content "] [class*="CallToActionLink"] svg path {
    color: var(--ctp-crust) !important;
    fill: var(--ctp-crust) !important;
  }

  /* ============================================================
     LIVE PAGES  (bbc.com/news/live/… and the Sport live streams — ssrcss)
     A page type the theme never covered: the whole live stream ships a solid
     #fff StreamContainer, an #f8f8f8 "Summary" panel, #f8f8f8 post-action
     rows, avatar tiles and pagination buttons. Our generic p/li/heading rules
     had already lightened the text → light-on-white, unreadable.
     ============================================================ */
  [class*="StreamContainer"],
  [class*="StreamWrapperStyle"],
  [class*="PostWrapper"],
  [class*="PostBorderWrapper"] {
    background-color: transparent !important;
    border-color: var(--ctp-surface0) !important;
  }
  [class*="EditorialTextWrapper"],
  [class*="PostActions"] {
    background-color: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface0) !important;
  }
  /* Contributor avatar tile — scoped to the post, since [class*="ImageWrapper"]
     alone also matches every Sport/News card image wrapper. */
  [class*="ContentPost"] [class*="ImageWrapper"],
  [class*="PageButtonContainer"] {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
  }
  /* The numbered page tiles inside the live-feed pagination are bare <a>s that
     keep a hardcoded #f8f8f8 fill (40×40 → under the audit big() floor) — our
     light number on it read white-on-white. Darken every tile; keep the
     aria-current page a lighter surface so it still reads as selected. */
  [class*="PageButtonContainer"] a {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
    border-color: var(--ctp-surface1) !important;
  }
  [class*="PageButtonContainer"] a[aria-current="page"] {
    background-color: var(--ctp-surface1) !important;
    color: var(--ctp-text) !important;
  }
  /* Each live post wraps its title in a bare <header>, which our global
     masthead rule painted mantle → a dark band behind every post headline. */
  [class*="ContentPost"] header,
  [class*="PostWrapper"] header {
    background-color: transparent !important;
  }
  /* The "New" flag on live posts newer than your last visit ships a solid-white
     pill with BBC teal #006666 text — it only renders for a returning reader
     (keyed off a per-session last-read marker), so a first-load scan never sees
     it, and on the dark stream it glares as a white chip. Scope to the Timestamp
     ancestor so the volatile "-New" Emotion suffix can't collide with the
     "News…"/"Newport…" components elsewhere. Repaint as a teal-filled badge with
     dark text — matching the yellow live-timestamp pill's dark-on-colour cue and
     keeping the "new update" prominence. */
  [class*="Timestamp"] [class*="-New"] {
    background-color: var(--ctp-teal) !important;
    color: var(--ctp-crust) !important;
  }
  /* Reader "Get Involved" comment bubbles (both news + sport live streams) ship
     a solid #fff SpeechBubble with a downward #fff ::after tail, plus a #f8f8f8
     reaction pill and a #f8f8f8 "Send us your…" uploader form. Our text rules
     lightened the copy → light-on-white, unreadable, and the DOM-bg scan flags
     the white panels. Darken the bubble (and its pseudo tail, which `*` never
     reaches) and the pill/form. */
  [class*="SpeechBubble"] {
    background-color: var(--ctp-mantle) !important;
    color: var(--ctp-subtext1) !important;
    border-color: var(--ctp-surface0) !important;
  }
  [class*="SpeechBubble"] * { color: var(--ctp-subtext1) !important; }
  [class*="SpeechBubble"]::after,
  [class*="SpeechBubble"]::before {
    border-top-color: var(--ctp-mantle) !important;
    border-bottom-color: var(--ctp-mantle) !important;
  }
  [class*="PostReactionWrapper"],
  [class*="UploaderWrapper"] {
    background-color: var(--ctp-mantle) !important;
  }
  /* The "Get involved" CTA (live-page contribution form, news + sport) is a
     native brand-yellow #ffd230 button whose label + chat-icon BBC paints black;
     our generic `button` rule flattened them to light → ~1.3:1 light-on-yellow.
     Restore dark text/icon. Scoped to the wrapper, which holds only this one
     yellow button, so the many transparent ssrcss ghost buttons that share the
     bare "Button" class keep their light text. */
  [class*="GetInvolvedButtonWrapper"] button,
  [class*="GetInvolvedButtonWrapper"] button span {
    color: var(--ctp-crust) !important;
  }
  [class*="GetInvolvedButtonWrapper"] button svg,
  [class*="GetInvolvedButtonWrapper"] button svg path {
    color: var(--ctp-crust) !important;
    fill: var(--ctp-crust) !important;
  }
  /* The in-play minute marker (StyledPeriod: "44'", "HT") ships BBC-Sport live teal
     #00ccc7 and our generic text rule flattened it to grey, dropping the live cue on
     every Scores & Fixtures row. Restore the readable Mocha teal (matching the LivePulse).
     NB: the same component also renders the plain past DATE ("29 JAN 2025") in a match
     page's head-to-head history, where BBC paints it near-black — those dates pick up the
     teal too. Nothing in the DOM distinguishes the two (the state lives only in a volatile
     Emotion hash), and the live minute marker is by far the commoner use. */
  [class*="StyledPeriod"] { color: var(--ctp-teal) !important; }
  /* VerticalLine is NOT a live indicator: it is the hairline between the two halves of a
     score ("0 | 0") and between the last-5 and latest cells of a league-table form guide.
     BBC paints it teal only while a match is actually in play and #c8c8c8 otherwise, so a
     blanket teal drew a live cue beside cancelled, postponed and not-yet-played matches
     and down every form guide. A neutral surface line matches the native resting state. */
  [class*="VerticalLine"] { border-color: var(--ctp-surface1) !important; }

  /* ---- Live MATCH page (ssrcss) ----
     A distinct surface from the live news stream above. Three solid light
     panels our rules never covered, each already carrying our lightened text:
       • the Live Reporting / Report / Scores / Line-ups tab strip (white <li>),
       • the "At a glance" key-points panel (#f8f8f8),
       • the Player Rater widget (#fff) with its #f8f8f8 information block.
     The tab strip also loses its active marker: the selected tab is flagged by
     `a { border-bottom: 3px #387b12 }` (transparent on the others), and our
     blanket `* { border-color }` repainted ALL of them the same surface line —
     erasing the indicator while drawing a phantom underline under every tab.
     Restore transparent + the BBC Sport accent (which BBC itself uses, as
     #ffd53c, on its own dark-background tabs). */
  li[class*="TabListItem"] {
    background-color: var(--ctp-mantle) !important;
  }
  li[class*="TabListItem"] a {
    color: var(--ctp-subtext1) !important;
    border-bottom-color: transparent !important;
  }
  li.selected[class*="TabListItem"] a {
    color: var(--ctp-text) !important;
    border-bottom-color: var(--ctp-yellow) !important;
  }
  [class*="GistWrapper"],
  [class*="PlayerRaterWrapper"],
  [class*="StyledInformationWrapper"] {
    background-color: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface0) !important;
  }
  /* Key-point bullets are 2x5px li::before discs filled a hardcoded #181818,
     invisible once the panel is dark. `*` never matches a pseudo-element. */
  [class*="GistWrapper"] li::before {
    background-color: var(--ctp-overlay2) !important;
  }
  hr[class*="Divider"] {
    background-color: var(--ctp-surface0) !important;
  }
  /* Player rows ship near-black #181818 names/scores — dark-on-dark once the
     rater is darkened. The rating bar's own #ffd230 fill is untouched; only
     its #d8d8d8 track is remapped. */
  [class*="PlayerRow"],
  [class*="PlayerRow"] * {
    color: var(--ctp-text) !important;
  }
  [class*="RatingBarWrapper"] {
    background-color: var(--ctp-surface1) !important;
  }
  /* "Player of the match" sits on the brand-yellow gradient banner; the
     generic heading rule turned it light-on-yellow (~1.4:1). */
  [class*="PlayerOfTheMatchWrapper"] h2 {
    color: var(--ctp-crust) !important;
  }

  /* ---- Live-match LINE-UPS tab (ssrcss) ----
     A whole tab the theme never covered: the team panels, the formation pitch, the
     starting-XI / substitutes lists and the Match Officials card all ship solid
     #fff/#f8f8f8, and our generic heading + p/li rules had already lightened their text
     → light-on-white across the entire tab. It is only rendered once you open the
     Line-ups tab of a match page, so no front-page scan ever sees it. The shirt-number
     discs carry each team's kit colour as an inline fill and are left alone. */
  [class*="TeamNameContainer"],
  [class*="TeamDetails"],
  [class*="FormationDividerContainer"],
  [class*="FormationContainer"],
  [class*="PlayerList"],
  [class*="SubstitutesSection"],
  [class*="MatchLineupsContainer"] [class*="-Card "] {
    background-color: var(--ctp-mantle) !important;
  }
  /* Hairline between formation and list ships #d8d8d8 — a bright rule on the dark panel. */
  [class*="FormationDivider"] {
    background-color: var(--ctp-surface0) !important;
  }
  /* The panel's own copy (Manager / Formation labels, Match Officials, player names in
     the pitch diagram) inherits a near-black #181818 from the container. */
  [class*="MatchLineupsContainer"],
  [class*="TeamDetailsLabel"],
  [class*="MatchOfficial"],
  [class*="OfficialsHeading"],
  [class*="PlayerNameContainer"],
  [class*="PlayerListItem"] {
    color: var(--ctp-subtext1) !important;
  }
  /* The pitch is an inline <svg> that paints its own #F8F8F8 surface and #606060
     markings. Attribute-matched so the two `fill="#fff"` <mask> paths — which MUST stay
     white or the mask stops working — are untouched. `-Pitch` matches only the svg
     component (FormationPitchContainer has no "-Pitch" substring). */
  [class*="-Pitch"] path[fill="#F8F8F8"] {
    fill: var(--ctp-mantle) !important;
  }
  [class*="-Pitch"] path[stroke="#F8F8F8"] {
    stroke: var(--ctp-mantle) !important;
  }
  [class*="-Pitch"] path[fill="#606060"],
  [class*="-Pitch"] ellipse[fill="#606060"] {
    fill: var(--ctp-overlay1) !important;
  }
  [class*="-Pitch"] path[stroke="#606060"],
  [class*="-Pitch"] ellipse[stroke="#606060"] {
    stroke: var(--ctp-overlay1) !important;
  }

  /* ---- Live-match MATCH STATS tab (ssrcss) ----
     Same story as Line-ups: a solid #fff wrapper with #f8f8f8 chart panels, our lightened
     headings on top of it. BBC keys the two teams by colour — home #ffd230, away #181818 —
     so once the panel is dark the away team's donut half, stat bars and legend swatch all
     disappear. The away side is always the SECOND of its sibling pair, which is a stable
     structural fact (its Emotion hash is not), so lift just those to a light neutral and
     leave the home yellow untouched. */
  [class*="MatchStatsWrapper"],
  [class*="DonutTitleContainer"],
  [class*="MatchStatsWrapper"] h3,
  [class*="MatchStatsWrapper"] [class*="-Wrapper "] {
    background-color: var(--ctp-mantle) !important;
  }
  /* Every label in here (team names, stat titles, per-team values, the donut legend)
     carries its own hardcoded #181818 or #606060, so the wrapper colour alone does not
     reach them. The swatches and bars are background-only, so a text rule cannot touch. */
  [class*="MatchStatsWrapper"],
  [class*="MatchStatsWrapper"] div,
  [class*="MatchStatsWrapper"] span,
  [class*="MatchStatsWrapper"] p {
    color: var(--ctp-subtext1) !important;
  }
  /* Stat-bar track (#f8f8f8) and the away team's half of every bar/legend/donut. */
  [class*="TeamBar"] {
    background-color: var(--ctp-surface0) !important;
  }
  [class*="TeamBar"] + [class*="TeamBar"] > [class*="ChartBar"],
  [class*="TeamName"] + [class*="KeyColourBox"],
  [class*="KeyWrapper"] + [class*="KeyWrapper"] [class*="KeyColourBox"] {
    background-color: var(--ctp-subtext1) !important;
  }
  [class*="SvgWrapper"] path[fill="#181818"] {
    fill: var(--ctp-subtext1) !important;
  }

  /* ---- League TABLES (bbc.com/sport/football/tables and every embedded standings
     table). Another uncovered surface: the head row is #f8f8f8 and every cell is #fff,
     while our light link colour had already painted the team names — so the table read
     light-on-white with near-black numbers beside them. Cells drop onto the base, the
     head row becomes a mantle band. The form-guide W/D/L pills keep their native
     green/red/grey fills and white letters. */
  [class*="OuterTableWrapper"],
  [class*="TableWrapper"],
  [class*="-Table "],
  [class*="CellsRow"],
  [class*="TableCell"] {
    background-color: transparent !important;
  }
  [class*="HeadingRow"],
  [class*="TableHeading"] {
    background-color: var(--ctp-mantle) !important;
  }
  /* Cells ship #606060 values and #181818 rank/points — both dark-on-dark once darkened. */
  [class*="TableCell"],
  [class*="TableHeading"],
  [class*="TableHeading"] [class*="-Element "] {
    color: var(--ctp-subtext1) !important;
  }
  [class*="-Rank "],
  [class*="-Points "] {
    color: var(--ctp-text) !important;
  }
  /* The "Key" legend and "Last Updated" strip under each table are separate #f8f8f8/#fff
     boxes outside the table element, so the cell reset above never reached them. */
  [class*="StyledKey"] {
    background-color: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface0) !important;
  }

  /* Sport masthead + primary nav bar ship a huge brand-yellow fill that
     swamps the dark theme and washes out its text. Darken the bar and keep
     the BBC Sport yellow as the wordmark / active accent instead. */
  [class*="Masthead"],
  [class*="PrimaryNavBarContainer"],
  [class*="MenuContainer-Primar"],
  /* The News error-page chrome (bbc.com/news/<bad-url>) nests a solid brand-red
     #b80000 PrimaryListContainer section-nav ("Home | UK | World | Business…")
     INSIDE the darkened MenuContainer-PrimaryNavBarContainer, so the child
     repaints the bar red on the dark page. Its links already inherit our light
     colour, so darkening the bar to mantle is all that's needed. */
  [class*="PrimaryListContainer"],
  [class*="SecondaryNav"],
  [class*="StyledNav"] {
    background-color: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface0) !important;
  }
  [class*="Masthead"] [class*="Heading"],
  [class*="Masthead"] h1,
  [class*="MastheadLink"] {
    color: var(--ctp-yellow) !important;
  }
  /* …but the "SPORT" wordmark is not a heading or a MastheadLink: it is an <svg>
     LogoIcon inside a LogoLink anchor, so the three selectors above never reached
     it and `[class*="Masthead"] a` (0,1,1) painted it plain light — the theme was
     dropping the BBC Sport identity the very rule above claims to keep (News gets
     its red wordmark; Sport got nothing). Win with a descendant match (0,2,0) and
     paint the artwork, which fills via currentColor. */
  [class*="Masthead"] [class*="LogoLink"] svg,
  [class*="Masthead"] [class*="LogoLink"] svg path,
  [class*="Masthead"] [class*="LogoIcon"],
  [class*="Masthead"] [class*="LogoIcon"] path {
    color: var(--ctp-yellow) !important;
    fill: var(--ctp-yellow) !important;
  }
  /* …but the ssrcss Masthead component is shared: Sport ships it brand-yellow,
     NEWS ships it brand-red (#b80000, on /news/live/* and other ssrcss News
     pages). The rule above paints the wordmark Sport-yellow regardless, so the
     NEWS live masthead lost the red News identity the theme keeps everywhere
     else (Dotcom NewsLogoContainer, LIVE badge, 404 StatusCode). The masthead's
     LogoLink anchor is href="/news" on News, href="/sport" on Sport — key off
     that to restore the brand red on the News wordmark only. Higher specificity
     than the yellow rule (extra attribute), so it wins regardless of order. */
  [class*="Masthead"] a[href="/news"] svg,
  [class*="Masthead"] a[href="/news"] svg path {
    color: var(--ctp-red) !important;
    fill: var(--ctp-red) !important;
  }
  [class*="Masthead"] a,
  [class*="PrimaryNavBarContainer"] a,
  [class*="MenuContainer-Primar"] a {
    color: var(--ctp-text) !important;
  }
  [class*="Masthead"] a:hover,
  [class*="PrimaryNavBarContainer"] a:hover { color: var(--ctp-yellow) !important; }
  /* active nav item keeps a yellow underline.
     NB: the two selectors below are dead on the live Sport nav — no element
     carries a "Selected" class, and the bar is not a border on the
     [aria-current] li. It is a 4px `a::after` painted pure black (readable on
     the brand-yellow bar, invisible on our dark one). `*` cannot reach a
     pseudo-element, so it survived every border rule. */
  [class*="PrimaryNavBarContainer"] [aria-current],
  [class*="PrimaryNavBarContainer"] [class*="Selected"] {
    color: var(--ctp-yellow) !important;
    border-color: var(--ctp-yellow) !important;
  }
  #product-navigation-menu [aria-current] a::after {
    background-color: var(--ctp-yellow) !important;
  }
  /* …but this product-nav is shared: on the ssrcss NEWS chrome (/news/live/*,
     modern 404) the active section-nav item is natively the News brand red
     #b80000, and the yellow rule above painted it Sport-yellow — a brand clash
     directly under the red NEWS wordmark and beside the red Politics sub-nav
     underline. The active News anchor is href="/news/…" (Sport is "/sport/…"),
     so restore the readable Mocha red on News only; Sport keeps its yellow.
     Higher specificity (extra attribute) wins regardless of order. */
  #product-navigation-menu [aria-current] a[href^="/news"]::after,
  #product-navigation-menu a[aria-current][href^="/news"]::after {
    background-color: var(--ctp-red) !important;
  }
  /* "More" sub-nav toggle ships raw brand yellow. The label + hamburger
     glyph are an <a>, so the generic [role="navigation"] a rule (0,1,1)
     out-specifies a bare [class*="StyledToggle"] (0,1,0) and paints them
     light → light-on-yellow, unreadable. Win with a descendant selector
     (0,2,0) and force the icon dark too. */
  [class*="StyledToggle"] {
    background-color: var(--ctp-yellow) !important;
    border-color: var(--ctp-yellow) !important;
  }
  [class*="ToggleContainer"] [class*="StyledToggle"],
  [class*="StyledToggle"], [class*="StyledToggle"] span {
    color: var(--ctp-crust) !important;
  }
  [class*="StyledToggle"] svg, [class*="StyledToggle"] svg path {
    color: var(--ctp-crust) !important;
    fill: var(--ctp-crust) !important;
  }
  /* …but the "More" toggle is the shared News/Sport StyledToggle: Sport ships it
     brand-yellow #ffd230, NEWS ships it brand-red #b80000 (on /news/live/* and the
     modern ssrcss 404). The unconditional yellow rule above painted the NEWS toggle
     Sport-yellow — a brand clash beside the red NEWS wordmark and the red active
     section-nav underline the theme already restores. The toggle's own href is the
     menu anchor (#product-navigation-menu, identical on both), so scope by the
     product-nav <nav aria-label="BBC News"> ancestor (Sport's is "BBC Sport") to
     repaint it the readable Mocha red on News only. Higher specificity than the
     yellow rule; the dark crust label/icon above already reads on the light red. */
  nav[aria-label="BBC News"] [class*="StyledToggle"] {
    background-color: var(--ctp-red) !important;
    border-color: var(--ctp-red) !important;
  }

  /* ============================================================
     LEGACY "ORB" GLOBAL HEADER  (bbc.com/weather and the other legacy
     products the domain() rule covers). A third chrome besides Dotcom and
     ssrcss: a full-width #fff bar. Our light link colour left the whole
     Home/News/Sport/Weather nav white-on-white. The BBC blocks logo here is
     a black-filled <svg> (and on the 404 page a black base64 PNG), so it has
     to be lifted with the bar or it vanishes.
     ============================================================ */
  #orbit-header, #orb-header, #orb-banner,
  .orb-nav-pri, .orb-nav-pri-white,
  .orb-skip-links h2, .orb-skip-links a {
    background-color: var(--ctp-mantle) !important;
    color: var(--ctp-text) !important;
  }
  #homepage-link svg, #homepage-link svg path {
    fill: var(--ctp-text) !important;
    color: var(--ctp-text) !important;
  }
  #orbit-search-button, .orbit-search__button {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
    border-color: var(--ctp-surface1) !important;
  }
  /* Legacy #bbccookies consent prompt (first-visit, logged-out). The bar itself is
     natively dark, but its inline "cookies" link is amber #f6a21d and our blanket `a`
     colour left it indistinguishable from the copy around it (BBC draws no underline),
     so the only in-sentence link on the page reads as plain text. Restore the accent. */
  #bbccookies a,
  #bbccookies-prompt a {
    color: var(--ctp-yellow) !important;
  }
  /* BBC serves TWO shapes of this bar and .banner-button means something different in
     each: on "Let us know you agree to cookies" the actions are unfilled amber text,
     on "Cookies on the BBC website" they are solid BBC-blue #0071f1 pills. Tinting the
     label amber suits the first and puts ~3.5:1 amber-on-blue on the second. Give both
     the same dark pill so the actions read as buttons either way. Higher specificity
     than the link rule above, so it wins on the anchor-flavoured variants too. */
  #bbccookies .banner-button,
  #bbccookies-prompt .banner-button {
    background-color: var(--ctp-surface1) !important;
    color: var(--ctp-yellow) !important;
    border-color: var(--ctp-overlay1) !important;
  }
  /* The ssrcss ConsentBanner (the same prompt on Sport/ssrcss pages) is a third shape:
     an already-dark section whose accept/reject actions are solid BBC-blue #0071f1 with
     white labels. Our generic `button` colour dimmed those labels to ~3:1 on the blue.
     Use the theme's own primary-button treatment — light Mocha blue, dark label. */
  [class*="ConsentBanner"] button {
    background-color: var(--ctp-blue) !important;
    color: var(--ctp-crust) !important;
    border-color: var(--ctp-blue) !important;
  }

  /* BBC Weather (wr- plus ssrcss hybrid): ad rail, the video "media and text"
     block and the units/language settings strip all ship #eee/#f8f8f8/#fff.
     Both blocks carry their config in the id, so anchor on the id prefix
     rather than the volatile ssrcss hash. */
  .wr-c-advert, .wr-c-advert__leaderboard {
    background-color: var(--ctp-crust) !important;
  }
  /* The BBC Weather masthead ships a full-width brand-blue #067eb3 band (the
     WEATHER wordmark + city search) that swamps the dark theme — the same loud
     brand-fill pattern the Sport masthead has, handled the same way: darken the
     band and keep the wordmark as the brand accent. The wordmark is an <svg>
     filled via currentColor, so tint it the Mocha sky-blue to keep the Weather
     identity (as News keeps red, Sport keeps yellow). */
  .wr-c-masthead__wrap {
    background-color: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface0) !important;
  }
  .wr-c-masthead__weather-logo svg,
  .wr-c-masthead__weather-logo svg path,
  .wr-c-weather-logo__svg, .wr-c-weather-logo__svg path {
    color: var(--ctp-sky) !important;
    fill: var(--ctp-sky) !important;
  }
  .ls-c-search__submit {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
  }
  [id^="media-and-text-block"] [class*="StyledContainer"],
  [id^="media-and-text-block"] [class*="MediaMetadataStyle"],
  [id^="page-settings"] [class*="StyledWrapper"] {
    background-color: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface0) !important;
  }

  /* ---- BBC Weather LOCATION FORECAST  (bbc.com/weather/<id>, wr-* BEM) ----
     The masthead rules above cover only the top band; the whole forecast body — the
     day carousel tiles, the day/Tonight summary, the hourly time-slot table, the astro
     + environment bars and the map controls — ships solid #fff/#f8f8f8 panels with
     near-black text authored for the old light page (a page-level pass sees 14 white
     surfaces + 30 sub-floor tiles here). Every wr- class is stable (not a hash). Darken
     the panels and lift the values; the coloured weather-type icons paint via explicit
     fills (not currentColor), so a colour rule leaves them intact, and the compass /
     back-to-top glyphs — which DO paint near-black — are lifted just below. */
  #wr-forecast,
  #wr-forecast .wr-day__content,
  #wr-forecast [class*="wr-time-slot"],
  #wr-forecast .wr-see-more,
  /* the day-summary strip is a separate full-width #fff row only in the mobile layout */
  #wr-forecast .wr-day-summary {
    background-color: var(--ctp-base) !important;
  }
  /* `.wr-c-map-controls` is a full-size TRANSPARENT overlay layer stretched across the
     whole rain/pressure map (1248x418), not a bar: giving it an opaque background hides
     the map entirely. Same for `.wr-c-map-controls__timeslider` and most
     `weathermap__timeslider*` nodes — natively every one is transparent. Only the
     timeline STRIP is a real surface (#fff), so darken exactly that. */
  .weathermap__timeslider__timeline-wrapper {
    background-color: var(--ctp-mantle) !important;
  }
  /* The timeslider's forecast tabs encode selection by fill: the active one is #fff with
     BBC-blue #149edc text, the others mid-grey #545658 with white text. A blanket dark
     fill made all three identical — no "you are here". Keep the active tab a lighter
     surface with the Mocha sky accent. */
  .weathermap__timeslider__tab {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-subtext0) !important;
  }
  .weathermap__timeslider__tab--active {
    background-color: var(--ctp-surface1) !important;
    color: var(--ctp-sky) !important;
  }
  /* The scrub track is a near-white 1016x16 strip — invisible on BBC's white bar, a
     glaring band on ours. The handle keeps its light fill (it IS the grab affordance)
     and its brand-blue ring, which the blanket `* { border-color }` reset had flattened. */
  .weathermap__timeslider__slider {
    background-color: var(--ctp-surface0) !important;
  }
  .weathermap__timeslider__slider__handle {
    border-color: var(--ctp-sky) !important;
  }
  /* The step arrows are brand blue when usable and #e6e8ea when there is no further
     timeslot — on a dark bar that leaves the DISABLED arrow the brightest thing in the
     widget. Dim it back below the enabled one. */
  .weathermap__timeslider__prev[disabled],
  .weathermap__timeslider__next[disabled] {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-overlay1) !important;
  }
  /* The map timeslider's day-divider labels ("Fri"/"Sat") ship near-black
     #545658 — dark-on-dark over the darkened control bar. This widget is not
     inside #wr-forecast, so the forecast text-lift never reaches them. Lift to
     a readable muted Mocha (the play glyph + tick marks are already light). */
  [class*="weathermap__timeslider__group-label"] {
    color: var(--ctp-subtext0) !important;
  }
  #wr-forecast,
  #wr-forecast *,
  .wr-c-astro-data, .wr-c-astro-data *,
  .wr-c-environmental-data, .wr-c-environmental-data *,
  .wr-c-weather-watchers-report, .wr-c-weather-watchers-report * {
    color: var(--ctp-subtext1) !important;
  }
  /* Every BBC weather-type glyph (sun/cloud/moon) is a <use> of an SVG symbol whose
     first shape is a #FFFFFF rounded-tile background (wr-icon-*__svg-background) —
     invisible on the old white page, a glaring white square behind each icon on ours.
     Darken the tile to the panel base so only the coloured art shows; the art paints
     via its own per-shape fills and is untouched. */
  [class*="wr-icon"][class*="__svg-background"] {
    fill: var(--ctp-base) !important;
  }
  /* The compass wind-direction disc and the back-to-top chevron are near-black symbol
     art that must stay a visible control, so give those a lighter surface fill. */
  .wr-icon-wind-direction__svg-circle,
  [class*="wr-icon-gel"][class*="__svg-background"] {
    fill: var(--ctp-surface1) !important;
  }
  /* The day/hour carousel scroll arrows are a solid brand-blue #149edc button. Re-tint to
     a dark surface tile so the rail stays monochrome and the light chevron reads. */
  [class*="wr-carousel-arrow"] {
    background-color: var(--ctp-surface0) !important;
  }
  /* The written "Latest forecast for <city>" panel below the map is an ssrcss
     TextBlockContainer shipped solid #fff — our text rule already lightened its copy, so
     it read light-on-white. Drop it onto the base; the media-and-text StyledContainer
     around it is already darkened above. */
  [class*="TextBlockContainer"] {
    background-color: transparent !important;
  }
  /* The current-conditions "Observations" band is a same-document micro-app mounted on
     #weather-observations (its id carries a hardcoded corePalette=light) — a solid-#fff
     WeatherObservationsContainer whose own headings/values stay near-black. Darken the
     band and lift every value; its moon/wind glyphs paint via currentColor so the text
     colour carries them too. */
  [id^="weather-observations"] [class*="WeatherObservationsContainer"] {
    background-color: var(--ctp-base) !important;
  }
  [id^="weather-observations"],
  [id^="weather-observations"] * {
    color: var(--ctp-subtext1) !important;
  }

  /* 404 page ships its own tiny chrome: a white .nav inside .header, with the
     BBC blocks logo as a black base64 PNG. Darken the bar and invert the
     bitmap so the wordmark survives (light blocks, dark letters). */
  .header > .nav {
    background-color: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface0) !important;
  }
  .header > .nav .logo img {
    filter: invert(1) !important;
  }
  /* The big "404" kicker ships brand #b80000 — 2.2:1 on the mantle heading
     block, below the 3:1 floor even for large bold text. */
  h1 span.StatusCode {
    color: var(--ctp-red) !important;
  }
  /* The site-wide "Sorry, we couldn't find that page" 404 (bbc.com/<bad-url>, distinct
     from the News one above) keeps two light slabs the theme never covered: a #e4e4e4
     search box + submit tile, and a mid-grey #4c4c4c footer band that is a div.footer,
     not a <footer>, so the footer rule never reached it. The purple error banner above
     them is BBC's own error colour and stays. */
  form.search-container,
  form.search-container button {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
    border-color: var(--ctp-surface1) !important;
  }
  /* Its magnifier is a black base64 PNG background-image, so no fill/color rule reaches
     it — invert the bitmap the way the News 404 logo is handled. */
  form.search-container button .search-icon {
    filter: invert(1) !important;
  }
  #foot.footer {
    background-color: var(--ctp-crust) !important;
    color: var(--ctp-subtext0) !important;
  }

  /* ============================================================
     ADS — dark-frame the slot containers (the cross-origin iframe
     itself can't be themed, but its container shouldn't glare white).
     ============================================================ */
  [data-component="ad-slot"],
  [data-component="advertisement-block"],
  [data-testid="ad-unit"],
  [class*="Advertisement"],
  [class*="AdSlot"],
  [class*="dotcom-ad"],
  .dotcom-ad,
  [id^="dotcom-"],
  /* Sport (ssrcss) MPU / sticky ad slots ship a bare white container that
     glares before the cross-origin ad iframe fills it. */
  #sticky-mpu,
  [id*="mpu-side-aside"],
  [id="advert"] {
    background-color: var(--ctp-crust) !important;
    border-color: var(--ctp-surface0) !important;
    color: var(--ctp-overlay1) !important;
  }

  /* Piano/Tinypass "Register for a free BBC account" modal (fires on article
     pages after a few reads). Its backdrop ships a white rgba(255,255,255,.7)
     scrim in the MAIN document that washes the whole page to light-grey. Darken
     it to a proper dark scrim. The modal card itself is a cross-origin Piano
     iframe (tp-iframe-wrapper > iframe.offer-*) → unthemeable, like an ad. */
  .tp-backdrop {
    background-color: rgba(17, 17, 27, 0.7) !important;
  }
  .tp-modal-title, .tp-close {
    background-color: var(--ctp-mantle) !important;
    color: var(--ctp-text) !important;
  }

  /* Taboola sponsored-content feed (rendered INLINE below articles, not in
     an iframe → themeable). Our page-darkening left its hardcoded near-black
     card titles/descriptions (#141414) dark-on-dark and its branding line a
     too-dim #545658, plus a light-grey rbox pseudo-panel (#e4e4e4, 161px).
     Lift the text to readable Mocha and darken the panel. Targets Taboola's
     stable global classes, scoped to the widget so nothing else is touched. */
  [id*="taboola"] .video-title,
  [id*="taboola"] .video-label,
  .trc_rbox .video-title, .trc_rbox .video-label,
  .tbl-feed-header, .tbl-feed-header * {
    color: var(--ctp-text) !important;
  }
  [id*="taboola"] .video-description,
  [id*="taboola"] .branding, [id*="taboola"] .branding *,
  .trc_rbox .video-description,
  .trc_rbox .branding, .trc_rbox .branding * {
    color: var(--ctp-subtext0) !important;
  }
  #rbox-t2v::before, #rbox-t2v::after,
  .trc_rbox_div::before, .trc_rbox_div::after { background-color: var(--ctp-mantle) !important; }
  /* The "Taboola Feed" ad-disclosure wordmark is black SVG artwork delivered as
     a background-image, so no colour rule can reach it — it reads ~1.2:1 on the
     base. Invert the artwork instead. */
  .tbl-feed-header-logo {
    filter: invert(1) !important;
  }
  /* Taboola's ad-choices popover and its "hide this ad" overlay are white
     panels kept at visibility:hidden until you click their control, so a
     load-time scan never sees them; our light link/text colours would land on
     white. The popover's caret is a border triangle whose transparent sides
     our blanket `* { border-color }` filled in, squaring it off. */
  .trc_exclude_overlay, .trc_popover {
    background-color: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface1) !important;
    color: var(--ctp-text) !important;
  }
  .trc_popover_arrow {
    border-top-color: transparent !important;
    border-left-color: transparent !important;
    border-right-color: transparent !important;
    border-bottom-color: var(--ctp-mantle) !important;
  }

  /* ============================================================
     FORMS / INPUTS / BUTTONS
     ============================================================ */
  input, textarea, select {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
    border-color: var(--ctp-surface1) !important;
  }
  input::placeholder, textarea::placeholder { color: var(--ctp-overlay1) !important; }
  button,
  [class*="ButtonStyled"],
  [class*="StyledButton"],
  [class*="Button-styles"],
  [class*="ButtonBase"],
  [class*="GhostButton"] {
    color: var(--ctp-text) !important;
  }
  /* Primary action buttons keep a confident accent */
  [class*="PrimaryButton"],
  button[class*="Primary"] {
    background-color: var(--ctp-blue) !important;
    color: var(--ctp-crust) !important;
    border-color: var(--ctp-blue) !important;
  }

  /* ============================================================
     FOOTER (both frontends)
     ============================================================ */
  footer,
  [class*="FooterStyled"],
  [class*="Footer-styles"],
  [class*="StyledFooter"] {
    background-color: var(--ctp-crust) !important;
    color: var(--ctp-subtext0) !important;
    border-color: var(--ctp-surface0) !important;
  }
  footer a,
  [class*="FooterStyled"] a,
  [class*="StyledFooter"] a {
    color: var(--ctp-subtext1) !important;
  }
  footer a:hover { color: var(--ctp-text) !important; }
  /* "Follow BBC on" row: the x / facebook / linkedin glyphs inherit
     fill:currentColor and lift with the footer link colour, but instagram,
     tiktok and youtube carry a literal fill="black" attribute on the <path>
     that beats the inherited fill — three of six icons vanish on the crust
     footer. Paint the paths explicitly. */
  [class*="SocialFollowUs"] svg path {
    fill: var(--ctp-subtext1) !important;
  }

  /* ============================================================
     GENERIC TEXT / LINK CATCH (within news+sport scope only)
     ============================================================ */
  h1, h2, h3, h4, h5, h6 { color: var(--ctp-text) !important; }
  p, li, dd, dt, figcaption, summary, label, caption, address, cite {
    color: var(--ctp-subtext1) !important;
  }

  /* ============================================================
     SEMANTIC / BRAND COLOURS — preserve, tuned for dark
     ============================================================ */
  /* BBC News red rail / breaking-news flags / live indicators */
  [class*="Breaking"],
  [class*="LiveLabel"],
  [class*="Live-"],
  [data-testid="live-icon"],
  [class*="PulseLabel"],
  /* Dotcom card-heading "LIVE" badge ships hardcoded brand red #eb0000 —
     ~3.3:1 on the Mocha base (a WCAG-AA fail for the small bold caps), and the
     [class*="Live*"] hooks above don't catch it (its class is …ContentTypeLabel).
     Lift it to the readable Mocha red so the live signal still reads. */
  [class*="IndexCardHeading-styles__ContentTypeLabel"] {
    color: var(--ctp-red) !important;
  }
  [class*="Breaking"] [class*="Headline"],
  [class*="Breaking"] a { color: var(--ctp-red) !important; }

  /* Sport (ssrcss) live pulse ships brand teal #006666 on the "LIVE" caps AND
     its SVG pulse dot — ~2.3:1 dark-on-dark on the Mocha base, near-invisible.
     Lift to the Mocha teal so it keeps the BBC-Sport live cue but reads. */
  [class*="LivePulse"],
  [class*="LivePulse"] * {
    color: var(--ctp-teal) !important;
  }
  [class*="LivePulse"] svg,
  [class*="LivePulse"] svg path,
  [class*="LivePulse"] svg circle {
    fill: var(--ctp-teal) !important;
  }
  /* Sport result wins/losses + status accents.
     NB: a bare [class*="Win"] also matches the Dotcom "Windsor" lead-promo
     component (Windsor-styles__…) and painted every word of the newsletter /
     featured promo card green. Match the full "Winner" token instead. */
  [class*="Winner"], [class*="Increase"] { color: var(--ctp-green) !important; }
  [class*="Loss"], [class*="Decrease"] { color: var(--ctp-red) !important; }
}
